return {api_version=1,id="EX1_275",name="Cone of Cold",text="<b>Freeze</b> a minion and the minions next to it, and deal $1 damage to them.",set="EXPERT1",type="spell",class="mage",rarity="common",spell_school="frost",cost=3,target_mode="required",targets=function(ctx)return ctx:minions()end,on_play=function(ctx,self,target)local r={target};for _,e in ipairs(ctx:adjacent_minions(target))do r[#r+1]=e end;cardlib.effects.damage_all(ctx, r,1);for _,e in ipairs(r)do ctx:freeze(e)end end}
